select date_trunc('day', reading_ts) as activity_day, count(case when device_code = 'DV-01' then 1 end) as dv_01_count, approx_percentile(pressure, array(0.25, 0.5, 0.75)) as pressure_quartiles, approx_percentile(temp_c, 0.9) as temp_c_p90, approx_percentile(pressure, array(0.25, 0.5, 0.75)) as pressure_quartiles_2, corr(humidity, status_bits) as corr_humidity_status_bits from device_readings group by date_trunc('day', reading_ts) having corr(humidity, status_bits) < 0 order by dv_01_count desc nulls first;
